import std.io

pub type AppError = Failed(String)

fn firstOver(limit: Int64) -> Int64 {
    for i in 0..10 {
        if i > limit { return i }
    }
    return 99
}

fn tally(n: Int64) effect io {
    for i in 0..n { io.println("fn-tick") }
    return
}

pub fn main() effect io -> Result<(), AppError> {
    let f = firstOver(4)
    if f == 5 { io.println("fn-ret-ok") } else { io.println("fn-ret-bad") }
    tally(2)
    return Ok(())
}
